/** Extract the first 1–3 meaningful word tokens from a drug name for fast prefix lookup */
function extractTokens(name: string): string[] {
  // Split on space, keep tokens that are mostly letters and ≥ 4 chars (the drug root)
  return name
    .split(/[\s,+/()[\]]+/)
    .filter((t) => /^[A-Za-z]{3,}/.test(t) && !/^(tab|cap|inj|inj\.|syr|mg|ml|ip|dp|dt|la|sr|er|hcl|mcg|iu|ius|ointment|cream|drops|spray|solution|suspension|gel|powder|sachet|infusion|elixir|rotacap|respules|nasal|buccal|oral|vaginal|eye|sublingual|suppository|patch|plain|extract|aqueous|colloid)$/i.test(t))
    .slice(0, 4);
}

// ─── Build final exported list ─────────────────────────────────────────────
export const HOSPITAL_DRUGS: HospitalDrug[] = RAW.map((r) => ({
  id: r.id,
  name: r.name,
  nameLower: r.name.toLowerCase(),
  category: r.category,
  tokens: extractTokens(r.name),
}));

export const HOSPITAL_CATEGORIES = [...new Set(HOSPITAL_DRUGS.map((d) => d.category))].sort();
